"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { api, type JobStatus } from "@/lib/api";

export function useGeneration() {
  const [job, setJob] = useState<JobStatus | null>(null);
  const [polling, setPolling] = useState(false);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const stop = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = null;
    setPolling(false);
  }, []);

  const startPolling = useCallback(
    (id: string) => {
      stop();
      setJob({
        request_id: id,
        status: "queued",
        stage: "queued",
        error: "",
        title: "",
        final_score: null,
        iterations_used: 0,
        detector: "",
        elapsed_seconds: 0,
      });
      setPolling(true);
      timerRef.current = setInterval(async () => {
        try {
          const s = await api.status(id);
          setJob(s);
          if (s.status === "completed" || s.status === "failed") {
            stop();
          }
        } catch {
          stop();
        }
      }, 2000);
    },
    [stop]
  );

  useEffect(() => () => stop(), [stop]);

  return { job, polling, startPolling, stop };
}

export type PostStatus = "queued" | "generating" | "completed" | "failed";

export interface Post {
  id: string;
  topic: string;
  title: string;
  status: PostStatus;
  stage: string;
  iterations_used: number;
  final_score: number | null;
  detector: string;
  error: string;
  created_at: string;
  content: string;
}

export interface Revision {
  id: string;
  iteration: number;
  ai_score: number | null;
  detector: string;
  content: string;
}

export interface PostDetail {
  post: Post;
  revisions: Revision[];
}

export interface JobStatus {
  request_id: string;
  status: PostStatus;
  stage: string;
  error: string;
  title: string;
  final_score: number | null;
  iterations_used: number;
  detector: string;
  elapsed_seconds: number | null;
}

export interface GenerateResponse {
  request_id: string;
  status: string;
  async: boolean;
}

export interface GenerateOptions {
  topic: string;
  max_iterations?: number;
  temperature?: number;
  max_tokens?: number;
}

export interface Health {
  status: string;
  mode: string;
}

import { MOCK_ENABLED, apiUrl } from "./config";
import { mockApi } from "./api.mock";

async function request<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(apiUrl(url), {
    ...init,
    headers: init?.body
      ? { "Content-Type": "application/json", ...init.headers }
      : init?.headers,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const message =
      (data as { detail?: string }).detail ?? `Request failed (${res.status})`;
    throw new Error(message);
  }
  return data as T;
}

const realApi = {
  health: () => request<Health>("/api/health"),
  generate: (body: GenerateOptions) =>
    request<GenerateResponse>("/api/generate", {
      method: "POST",
      body: JSON.stringify(body),
    }),
  status: (id: string) => request<JobStatus>(`/api/status/${id}`),
  posts: () => request<{ posts: Post[] }>("/api/posts"),
  post: (id: string) => request<PostDetail>(`/api/posts/${id}`),
};

export const api = MOCK_ENABLED ? mockApi : realApi;

export const API_URL = (process.env.NEXT_PUBLIC_API_URL ?? "").replace(/\/$/, "");

export const MOCK_ENABLED = process.env.NEXT_PUBLIC_MOCK === "true";

export function apiUrl(path: string) {
  const p = path.startsWith("/") ? path : `/${path}`;
  return API_URL ? `${API_URL}${p}` : p;
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
